        $contents = [
            ['key' => 'about_title', 'value_ar' => 'عن منصة كُنوز التعليمية', 'value_en' => 'About Konoz Al-Quran', 'group' => 'about'],
            ['key' => 'about_content', 'value_ar' => 'منصة منصة كُنوز التعليمية هي منصة تعليمية متكاملة تهدف إلى تعليم القرآن الكريم وتحفيظه بأحدث الأساليب التعليمية. نقدم بيئة تعليمية متميزة تجمع بين العراقة والحداثة في تعليم كتاب الله.', 'value_en' => 'Konoz Al-Quran is an integrated educational platform aimed at teaching and memorizing the Holy Quran using the latest educational methods. We provide a distinguished educational environment that combines tradition and modernity in teaching the Book of Allah.', 'group' => 'about'],
            ['key' => 'mission', 'value_ar' => 'نشر العلم الشرعي وتعليم القرآن الكريم بأسلوب ميسر ومتقن يناسب جميع الفئات العمرية.', 'value_en' => 'Spreading Islamic knowledge and teaching the Holy Quran in an accessible and proficient manner suitable for all age groups.', 'group' => 'about'],
            ['key' => 'vision', 'value_ar' => 'أن نكون المنصة الرائدة في تعليم القرآن الكريم على مستوى العالم العربي والإسلامي.', 'value_en' => 'To be the leading platform in teaching the Holy Quran in the Arab and Islamic world.', 'group' => 'about'],
            ['key' => 'why_us_1_title', 'value_ar' => 'معلمات متخصصات', 'value_en' => 'Specialized Teachers', 'group' => 'why_us'],
            ['key' => 'why_us_1_desc', 'value_ar' => 'نخبة من المعلمات المجازات والحاصلات على إجازات في القرآن الكريم.', 'value_en' => 'An elite group of certified female teachers with Ijazas in the Holy Quran.', 'group' => 'why_us'],
            ['key' => 'why_us_2_title', 'value_ar' => 'منهجية متكاملة', 'value_en' => 'Integrated Methodology', 'group' => 'why_us'],
            ['key' => 'why_us_2_desc', 'value_ar' => 'منهج تعليمي شامل يغطي التجويد والتفسير والحفظ والمراجعة.', 'value_en' => 'A comprehensive educational curriculum covering Tajweed, Tafsir, memorization, and revision.', 'group' => 'why_us'],
            ['key' => 'why_us_3_title', 'value_ar' => 'متابعة فردية', 'value_en' => 'Individual Follow-up', 'group' => 'why_us'],
            ['key' => 'why_us_3_desc', 'value_ar' => 'متابعة شخصية لكل طالبة مع تقارير دورية عن مستوى التقدم.', 'value_en' => 'Personal follow-up for each student with periodic progress reports.', 'group' => 'why_us'],
