            ['key' => 'why_us_4_desc', 'value_ar' => 'مواعيد مرنة تناسب جميع الطالبات مع إمكانية اختيار الوقت المناسب.', 'value_en' => 'Flexible timings suitable for all students with the ability to choose the appropriate time.', 'group' => 'why_us'],
