            ['key' => 'linguistics_intro_heading', 'value_ar' => 'ماذا نُقدم لطفلكِ؟', 'value_en' => 'What do we offer your child?', 'group' => 'linguistics'],
            ['key' => 'linguistics_intro_point_1', 'value_ar' => 'تأسيس لغوي متكامل من الحروف إلى القراءة المستقلة بمنهجية متدرجة ومدروسة.', 'value_en' => 'Integrated linguistic foundation from letters to independent reading with a progressive, well-studied methodology.', 'group' => 'linguistics'],
            ['key' => 'linguistics_intro_point_2', 'value_ar' => 'مناهج حديثة تناسب الناطقين بالعربية وغير الناطقين بها بمستويات متدرجة.', 'value_en' => 'Modern curricula suitable for native and non-native Arabic speakers at progressive levels.', 'group' => 'linguistics'],
            ['key' => 'linguistics_intro_point_3', 'value_ar' => 'متابعة فردية مستمرة وتقارير دورية مفصلة للأهالي عن تقدم الطفل.', 'value_en' => 'Continuous individual follow-up and detailed periodic reports for parents on the child\'s progress.', 'group' => 'linguistics'],
