            ['key' => 'linguistics_axes_lead', 'value_ar' => 'أربعة محاور متكاملة تُبنى على بعضها لتحقيق التمكين اللغوي الكامل للطفل.', 'value_en' => 'Four integrated axes that build on each other to achieve complete linguistic empowerment for the child.', 'group' => 'linguistics'],
