            ['key' => 'coding_intro_heading', 'value_ar' => 'ماذا يتعلم طفلكِ؟', 'value_en' => 'What will your child learn?', 'group' => 'coding'],
            ['key' => 'coding_intro_point_1', 'value_ar' => 'تأسيس قوي في التفكير المنطقي والحاسوبي وحل المشكلات منذ سن مبكرة.', 'value_en' => 'A strong foundation in logical and computational thinking and problem solving from an early age.', 'group' => 'coding'],
            ['key' => 'coding_intro_point_2', 'value_ar' => 'مشاريع عملية حقيقية يبنيها الطفل ويعرضها بنفسه مع ختام كل مرحلة.', 'value_en' => 'Real practical projects that the child builds and presents by themselves at the end of each stage.', 'group' => 'coding'],
            ['key' => 'coding_intro_point_3', 'value_ar' => 'مسارات متدرجة تناسب كل فئة عمرية من ٧ سنوات فأكثر.', 'value_en' => 'Progressive tracks suitable for every age group from age 7 and above.', 'group' => 'coding'],
